#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void layer_norm_kernel(
    const half* __restrict__ input,
    half* __restrict__ output,
    const half* __restrict__ weight,
    const half* __restrict__ bias,
    const float* __restrict__ mean,
    const float* __restrict__ rstd,
    int64_t batch_size,
    int64_t features,
    int64_t dim1,
    int64_t dim2
) {
    // Calculate total elements per sample
    int64_t sample_elements = features * dim1 * dim2;

    // Thread index
    int64_t tid = blockIdx.x * blockDim.x + threadIdx.x;

    // Each thread processes one element
    if (tid >= batch_size * sample_elements) return;

    // Determine which sample this thread is working on
    int64_t sample_idx = tid / sample_elements;
    int64_t elem_idx = tid % sample_elements;

    // Get the mean and rstd for this sample
    float sample_mean = mean[sample_idx];
    float sample_rstd = rstd[sample_idx];

    // Convert input to float for computation
    float x_val = __half2float(input[tid]);

    // Apply layer normalization: (x - mean) * rstd * weight + bias
    float result = (x_val - sample_mean) * sample_rstd;

    // Apply scale and bias
    result = result * __half2float(weight[elem_idx % features]) + __half2float(bias[elem_idx % features]);

    // Store result back to output
    output[tid] = __float2half(result);
}

// Helper function to compute mean and rstd
__global__ void compute_stats_kernel(
    const half* __restrict__ input,
    float* __restrict__ mean,
    float* __restrict__ rstd,
    int64_t batch_size,
    int64_t features,
    int64_t dim1,
    int64_t dim2
) {
    int64_t sample_idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (sample_idx >= batch_size) return;

    int64_t sample_elements = features * dim1 * dim2;
    int64_t start_idx = sample_idx * sample_elements;

    // Compute sum and sum of squares
    float sum = 0.0f;
    float sum_sq = 0.0f;

    for (int64_t i = 0; i < sample_elements; ++i) {
        float val = __half2float(input[start_idx + i]);
        sum += val;
        sum_sq += val * val;
    }

    // Compute mean and variance
    float sample_mean = sum / sample_elements;
    float variance = sum_sq / sample_elements - sample_mean * sample_mean;

    // Compute reciprocal standard deviation (with epsilon for numerical stability)
    float eps = 1e-5f;
    float sample_rstd = rsqrtf(variance + eps);

    mean[sample_idx] = sample_mean;
    rstd[sample_idx] = sample_rstd;
}
"""

