        # Get dimensions
        batch_size = x.shape[0]
        features = self.normalized_shape[0]
        dim1 = self.normalized_shape[1]
        dim2 = self.normalized_shape[2]

        # Flatten the tensor for processing
        original_shape = x.shape
        x_flat = x.view(batch_size, -1)

